// Glyph index for codepoint `cp`, or the '?' glyph.
static int qfont_index(unsigned cp) {
    if (cp >= 0x20 && cp <= 0x7E) return (int)(cp - 0x20);
    if (cp >= 0xA0 && cp <= 0xFF) return (int)(cp - 0xA0) + 95;
    return '?' - 0x20;
}
